-- ---------- accounts that also sign in with Google ----------
INSERT INTO user_identity (user_id, provider, provider_subject, created_at, last_login_at)
SELECT b.user_id, 'GOOGLE', (100000000000000000000 + abs(hashtext(b.username)) * 1000003::numeric)::text,
       u.created_at, u.last_login_at
  FROM seed_new_buyer b JOIN user_account u ON u.id = b.user_id
 WHERE abs(hashtext(b.username || 'google')) % 4 = 0;

-- ---------- admin activity log ----------
-- Rebuilt from what the data says happened, in the words the services use.
INSERT INTO audit_log (occurred_at, actor_user_id, action, target_type, target_id, summary, metadata, ip_address)
SELECT x.at, x.actor, x.action, x.target_type, x.target_id, x.summary, x.meta,
       CASE WHEN x.actor IS NULL THEN NULL ELSE ('203.0.113.' || (10 + abs(hashtext(x.target_id)) % 40))::inet END
  FROM (
    SELECT p.verified_at AS at, p.verified_by AS actor, 'PAYMENT_APPROVED' AS action, 'PAYMENT' AS target_type,
           p.id::text AS target_id, 'Approved payment #' || p.id || ' for order #' || p.sales_order_id AS summary,
           jsonb_build_object('orderId', p.sales_order_id, 'amount', p.amount) AS meta
      FROM payment p WHERE p.status = 'SUCCEEDED' AND p.method = 'BANK_TRANSFER' AND p.verified_at IS NOT NULL
    UNION ALL
    SELECT p.verified_at, coalesce(p.verified_by, pg_temp.uid('admin')), 'PAYMENT_REJECTED', 'PAYMENT', p.id::text,
           'Rejected payment #' || p.id || ' for order #' || p.sales_order_id,
           jsonb_build_object('orderId', p.sales_order_id, 'amount', p.amount, 'reason', p.failure_reason)
      FROM payment p WHERE p.status = 'FAILED' AND p.verified_at IS NOT NULL AND p.failure_reason IS NOT NULL
    UNION ALL
    SELECT po.approved_at, po.approved_by, 'PAYOUT_APPROVED', 'PAYOUT', po.id::text, 'Approved payout #' || po.id,
           jsonb_build_object('sellerProfileId', po.seller_profile_id, 'amount', po.amount)
      FROM payout po WHERE po.approved_at IS NOT NULL
    UNION ALL
    SELECT po.approved_at + interval '6 hours', po.approved_by, 'PAYOUT_PROCESSING', 'PAYOUT', po.id::text,
           'Started transfer for payout #' || po.id, jsonb_build_object('sellerProfileId', po.seller_profile_id, 'amount', po.amount)
      FROM payout po WHERE po.status IN ('PROCESSING', 'PAID', 'FAILED') AND po.approved_at IS NOT NULL
    UNION ALL
    SELECT po.paid_at, pg_temp.uid('admin'), 'PAYOUT_PAID', 'PAYOUT', po.id::text, 'Paid payout #' || po.id,
           jsonb_build_object('sellerProfileId', po.seller_profile_id, 'amount', po.amount, 'reference', po.transfer_reference)
      FROM payout po WHERE po.status = 'PAID'
    UNION ALL
    SELECT po.requested_at + interval '1 day', pg_temp.uid('admin'),
           CASE po.status WHEN 'REJECTED' THEN 'PAYOUT_REJECTED' ELSE 'PAYOUT_FAILED' END, 'PAYOUT', po.id::text,
           CASE po.status WHEN 'REJECTED' THEN 'Rejected payout #' ELSE 'Marked failed payout #' END || po.id,
           jsonb_build_object('sellerProfileId', po.seller_profile_id, 'amount', po.amount, 'reason', po.rejection_reason)
      FROM payout po WHERE po.status IN ('REJECTED', 'FAILED')
    UNION ALL
    SELECT r.processed_at, coalesce(r.processed_by, pg_temp.uid('admin')), 'REFUND_PROCESSED', 'REFUND', r.id::text,
           'Completed refund #' || r.id, jsonb_build_object('orderId', r.sales_order_id, 'amount', r.amount)
      FROM refund r WHERE r.status = 'PROCESSED' AND r.processed_at IS NOT NULL
    UNION ALL
    SELECT v.submitted_at, sp.user_id, 'SELLER_VERIFICATION_SUBMITTED', 'SELLER_VERIFICATION', v.id::text,
           'Seller submitted verification #' || v.id, jsonb_build_object('sellerProfileId', v.seller_profile_id)
      FROM seller_verification v JOIN seller_profile sp ON sp.id = v.seller_profile_id
    UNION ALL
    SELECT v.reviewed_at, v.reviewed_by,
           CASE v.status WHEN 'APPROVED' THEN 'SELLER_VERIFICATION_APPROVED' ELSE 'SELLER_VERIFICATION_REJECTED' END,
           'SELLER_VERIFICATION', v.id::text,
           CASE v.status WHEN 'APPROVED' THEN 'Approved' ELSE 'Rejected' END || ' seller verification #' || v.id,
           jsonb_build_object('sellerProfileId', v.seller_profile_id, 'reason', v.rejection_reason)
      FROM seller_verification v WHERE v.reviewed_at IS NOT NULL AND v.status IN ('APPROVED', 'REJECTED')
    UNION ALL
    SELECT p.created_at, p.created_by, 'CATALOG_PRODUCT_CREATED', 'CATALOG_PRODUCT', p.id::text,
           'Created product "' || p.name || '"', jsonb_build_object('gameId', p.game_id, 'slug', p.slug)
      FROM catalog_product p
    UNION ALL
    SELECT p.created_at + interval '20 minutes', p.created_by, 'CATALOG_IMAGE_ADDED', 'CATALOG_PRODUCT', p.id::text,
           'Added image #' || ci.id || ' to product #' || p.id,
           jsonb_build_object('imageId', ci.id, 'variantId', ci.catalog_variant_id, 'primary', ci.is_primary)
      FROM catalog_image ci JOIN catalog_product p ON p.id = ci.catalog_product_id
     WHERE ci.image_key LIKE 'seed/products/%'
    UNION ALL
    SELECT pg_temp.ago(400) + make_interval(days => s.id), pg_temp.uid('admin'), 'CARD_SET_CREATED', 'CARD_SET', s.id::text,
           'Created card set "' || s.name || '"', jsonb_build_object('gameId', s.game_id, 'code', s.code)
      FROM card_set s WHERE s.release_date IS NOT NULL
    UNION ALL
    SELECT c.created_at, c.created_by, 'COMMISSION_RULE_CREATED', 'COMMISSION_RULE', c.id::text,
           'Created commission rule #' || c.id, jsonb_build_object('scope', c.scope, 'ratePercent', c.rate_percent)
      FROM commission_rule c
    UNION ALL
    SELECT pg_temp.ago(d.n) - interval '2 hours', NULL, 'MARKET_PRICING_RUN', 'MARKET_PRICING',
           to_char(pg_temp.ago(d.n), 'YYYY-MM-DD'), 'Ran market pricing for ' || to_char(pg_temp.ago(d.n), 'YYYY-MM-DD'),
           jsonb_build_object('marketsComputed', 300 + (d.n * 37) % 120, 'listingsRepriced', (d.n * 13) % 40)
      FROM generate_series(0, 45) AS d(n)
    UNION ALL
    SELECT pg_temp.ago(d.n, 3), NULL, 'ORDERS_AUTO_RELEASED', 'JOB', 'escrow-auto-release',
           'Auto-completed ' || (1 + d.n % 4) || ' order(s) and released escrow',
           jsonb_build_object('completed', 1 + d.n % 4, 'failed', 0)
      FROM generate_series(1, 60, 3) AS d(n)
    UNION ALL
    SELECT pg_temp.ago(d.n, 5), NULL, 'UNPAID_ORDERS_EXPIRED', 'JOB', 'unpaid-order-expiry',
           'Cancelled ' || (1 + d.n % 2) || ' unpaid order(s)', jsonb_build_object('cancelled', 1 + d.n % 2, 'failed', 0)
      FROM generate_series(2, 60, 7) AS d(n)
    UNION ALL
    SELECT u.updated_at, pg_temp.uid('admin'), 'USER_STATUS_CHANGED', 'USER', u.id::text,
           'Changed status of user #' || u.id || ' to ' || u.status, jsonb_build_object('status', u.status)
      FROM user_account u WHERE u.status <> 'ACTIVE'
    UNION ALL
    SELECT ur.granted_at, ur.granted_by, 'USER_ROLE_GRANTED', 'USER', ur.user_id::text,
           'Granted role ' || r.code || ' to user #' || ur.user_id, jsonb_build_object('role', r.code)
      FROM user_role ur JOIN app_role r ON r.id = ur.role_id WHERE ur.granted_by IS NOT NULL
    UNION ALL
    SELECT s.updated_at, s.updated_by, 'SETTING_UPDATED', 'SETTING', s.setting_key, 'Updated setting ' || s.setting_key,
           jsonb_build_object('value', s.setting_value)
      FROM platform_setting s WHERE s.updated_by IS NOT NULL
    UNION ALL
    SELECT a.created_at, a.created_by, 'SEARCH_ALIAS_CREATED', 'SEARCH_ALIAS', a.id::text,
           'Added search alias "' || a.alias || '" -> "' || a.target || '"', jsonb_build_object('alias', a.alias, 'target', a.target)
      FROM search_alias a WHERE a.created_by IS NOT NULL
  ) x
 WHERE x.at IS NOT NULL AND x.at <= now()
 ORDER BY x.at;

