INSERT INTO search_query_log (q_norm, result_count, corrected_to, session_hash, created_at)
SELECT s.q,
       CASE WHEN s.typo_of IS NOT NULL THEN 0 ELSE
       (SELECT count(*) FROM catalog_product p
         WHERE p.is_active AND (lower(p.name) LIKE '%' || s.q || '%' OR lower(coalesce(p.name_local, '')) LIKE '%' || s.q || '%'
                                OR lower(p.card_number) = s.q)) END,
       s.typo_of,
       encode(sha256(convert_to('seed-session-' || (abs(hashtext(s.q || g.n)) % (40 + s.weight * 9)), 'UTF8')), 'hex'),
       pg_temp.ago((abs(hashtext(s.q || g.n || 't')) % 2900) / 100.0)
  FROM seed_search s
 CROSS JOIN LATERAL generate_series(1, s.weight * 6) AS g(n);
